-- Autoadjust.net database hardening.   Apply in the Supabase SQL Editor ONLY after you have approved it.
-- Changes permissions and one policy only. It does not drop, recreate or alter any table, row, key or relationship.
-- Safe to run twice. Undo with hardening_revert.sql (or the exact rollback generated by capture_rollback.sql).
begin;

-- 1. increment_usage is SECURITY DEFINER and was callable by anyone through the API (it could raise any user's usage counter).
--    The app never calls it. Only the backend (service role) keeps execute.
revoke execute on function public.increment_usage(uuid) from public, anon, authenticated;
grant  execute on function public.increment_usage(uuid) to service_role;

-- 2. Backend-only tables (the app reaches them only with the service-role key). Remove the default API grants:
--    RLS already blocked them (no policy); now the API roles cannot even attempt access.
revoke all on table public.app_records, public.soc_kev, public.soc_meta from anon, authenticated;

-- 3. Website-builder tables that belong to signed-in users. The anonymous role has no use for them.
--    Signed-in users keep their grants and their own-rows-only policies (own_projects, own_versions, own_usage).
revoke all on table public.projects, public.versions, public.usage from anon;

-- 4. Published sites stay publicly readable (app/serve/route.ts reads them with the anon key by slug or domain), but:
--    a) the anonymous role may read only the columns needed to serve a page, never project_id (the link to the private project);
--    b) the "public read" policy is limited to the anonymous role, so a signed-in user sees only their own sites
--       (policy sites_owner_write), not other people's project_id.
revoke all on table public.sites from anon;
grant select (slug, html, custom_domain, published_at) on table public.sites to anon;
drop policy if exists sites_public_read on public.sites;
create policy sites_public_read on public.sites for select to anon using (true);

commit;
